import type { ScannerHandedness } from "./types";

export const HANDEDNESS_STORAGE_KEY = "qr-scan-core:handedness";

export function readPersistedHandedness(storage?: Pick<Storage, "getItem"> | null): ScannerHandedness | null {
  try {
    const target = storage === undefined ? globalThis.localStorage : storage;
    const value = target?.getItem(HANDEDNESS_STORAGE_KEY);
    return value === "left" || value === "right" ? value : null;
  } catch {
    return null;
  }
}

export function persistHandedness(
  handedness: ScannerHandedness,
  storage?: Pick<Storage, "setItem"> | null,
): void {
  try {
    const target = storage === undefined ? globalThis.localStorage : storage;
    target?.setItem(HANDEDNESS_STORAGE_KEY, handedness);
  } catch {
    // Storage is best-effort in sandboxed and privacy-restricted contexts.
  }
}
