import { mapDialogActions } from "./dialog-actions";
import type {
  DialogAction,
  ScannerActionControls,
  ScannerActionTone,
  ScannerDialog,
  ScannerHandedness,
  ScannerPresentationOptions,
} from "./types";

export type ScannerActionKind = "jump" | "accept" | "cancel";

export interface ResolvedScannerPresentation {
  interaction: "unlocked" | "locked-glass";
  mirrorActionsInPrompt: boolean;
  dismissAfterAction: boolean;
  dismissOnScreenTap: boolean;
}

export interface PresentedScannerAction {
  id: string;
  label: string;
  promptLabel: string;
  tone: ScannerActionTone;
  kind: ScannerActionKind;
  disabled: boolean;
}

export interface PresentedActionGroups {
  neutral: PresentedScannerAction[];
  colored: PresentedScannerAction[];
}

export function resolveScannerPresentation(
  options: ScannerPresentationOptions = {},
  defaults: Partial<ResolvedScannerPresentation> = {},
): ResolvedScannerPresentation {
  return {
    interaction: options.interaction ?? defaults.interaction ?? "unlocked",
    mirrorActionsInPrompt: options.mirrorActionsInPrompt ?? defaults.mirrorActionsInPrompt ?? false,
    dismissAfterAction: options.dismissAfterAction ?? defaults.dismissAfterAction ?? false,
    dismissOnScreenTap: options.dismissOnScreenTap ?? defaults.dismissOnScreenTap ?? false,
  };
}

function present(
  action: { id: string; label: string; promptLabel?: string; tone?: ScannerActionTone; disabled?: boolean },
  kind: ScannerActionKind,
): PresentedScannerAction {
  return {
    id: action.id,
    label: action.label,
    promptLabel: action.promptLabel ?? action.label,
    tone: action.tone ?? (kind === "accept" ? "primary" : "neutral"),
    kind,
    disabled: action.disabled ?? false,
  };
}

export function mapScannerActionControls(controls: ScannerActionControls): PresentedActionGroups {
  const neutral: PresentedScannerAction[] = [];
  const colored: PresentedScannerAction[] = [];
  if (controls.jump) neutral.push(present(controls.jump, "jump"));
  if (controls.cancel) neutral.push(present(controls.cancel, "cancel"));
  if (controls.accept) colored.push(present(controls.accept, "accept"));
  return { neutral, colored };
}

function dialogControl(action: DialogAction, kind: ScannerActionKind): PresentedScannerAction {
  return present(action, kind);
}

export function mapDialogActionGroups(dialog: ScannerDialog): PresentedActionGroups {
  const { left, right } = mapDialogActions(dialog);
  return {
    neutral: left ? [dialogControl(left, "cancel")] : [],
    colored: right ? [dialogControl(right, "accept")] : [],
  };
}

export function orderPresentedActions(
  groups: PresentedActionGroups,
  handedness: ScannerHandedness,
): PresentedScannerAction[] {
  return handedness === "left"
    ? [...groups.colored, ...groups.neutral]
    : [...groups.neutral, ...groups.colored];
}
