import type { ScannerCodePresentation } from "./types";

export function copyableCodePayload(presentation: ScannerCodePresentation): string | null {
  if (presentation.state !== "known" && presentation.state !== "unknown") return null;
  return presentation.code?.length ? presentation.code : null;
}

export async function copyCodeToClipboard(presentation: ScannerCodePresentation): Promise<boolean> {
  const payload = copyableCodePayload(presentation);
  const writeText = globalThis.navigator?.clipboard?.writeText;
  if (!payload || !writeText) return false;
  try {
    await writeText.call(globalThis.navigator.clipboard, payload);
    return true;
  } catch {
    return false;
  }
}
