import type { DialogAction, ScannerDialog } from "./types";

const actionText = (action: DialogAction) => `${action.id} ${action.label}`.toLowerCase();

export const isDeleteDialogAction = (action: DialogAction): boolean => (
  action.tone === "delete" || /\b(delete|destroy|purge)\b/.test(actionText(action))
);

export const isConfirmDialogAction = (action: DialogAction): boolean => (
  action.tone === "primary"
  || action.tone === "danger"
  || isDeleteDialogAction(action)
  || /\b(confirm|continue|acknowledge|accept|apply|proceed|retry|save|overwrite|replace|reassign|yes|ok|okay)\b/.test(actionText(action))
);

export interface DialogActionSlots {
  left: DialogAction | null;
  right: DialogAction | null;
}

export function mapDialogActions(dialog: ScannerDialog): DialogActionSlots {
  const only = dialog.actions.length === 1 ? dialog.actions[0]! : null;
  const semanticRight = dialog.actions.length > 1
    ? dialog.actions.find(isConfirmDialogAction) ?? dialog.actions[dialog.actions.length - 1]!
    : only && isConfirmDialogAction(only) ? only : null;
  const left = dialog.actions.length > 1
    ? dialog.actions.find((action) => action !== semanticRight) ?? null
    : only && !semanticRight ? only : null;
  const right = semanticRight
    ? isDeleteDialogAction(semanticRight) ? { ...semanticRight, tone: "delete" as const } : semanticRight
    : null;
  return { left, right };
}
