export type DeleteStep = "none" | "idle" | "armed" | "confirming";

export const CONFIRM_DELETE_LABEL = "Confirm Delete";

export function advanceDeleteStep(step: DeleteStep): DeleteStep {
  if (step === "idle") return "armed";
  if (step === "armed") return "confirming";
  return step;
}

export const isDeleteConfirming = (step: DeleteStep) => step === "confirming";
