import type { Roi } from "./types";

export interface BuildInfoSnapshot {
  upstreamBranch: string;
  upstreamCommit: string;
  localBranch: string;
  localCommit: string;
}

export interface CameraFeedBuildInfoDecision {
  suppress: boolean;
  reveal: boolean;
  restoreRoi: Roi | null;
}

declare const __SEEK_QR_BUILD_INFO__: BuildInfoSnapshot | undefined;

const UNKNOWN_BUILD_INFO: BuildInfoSnapshot = {
  upstreamBranch: "unknown",
  upstreamCommit: "unknown",
  localBranch: "unknown",
  localCommit: "unknown",
};

export const CURRENT_BUILD_INFO: BuildInfoSnapshot = typeof __SEEK_QR_BUILD_INFO__ === "object"
  ? __SEEK_QR_BUILD_INFO__
  : UNKNOWN_BUILD_INFO;

const shortCommit = (commit: string) => commit === "unknown" ? commit : commit.slice(0, 6);

export function formatBuildInfo(product: string, info: BuildInfoSnapshot = CURRENT_BUILD_INFO): string {
  const upstreamLabel = `${product} - ${info.upstreamBranch}`;
  const localIndent = " ".repeat(Math.max(0, upstreamLabel.length - "local".length));
  return `${upstreamLabel}: (${shortCommit(info.upstreamCommit)})\n${localIndent}local: ${info.localBranch} (${shortCommit(info.localCommit)})`;
}

export class CameraFeedBuildInfoGesture {
  private readonly activeTouchPointers = new Set<number>();
  private readonly suppressedPointers = new Set<number>();
  private initialRoi: Roi | null = null;
  private revealed = false;

  begin(pointerId: number, pointerType: string, ctrlKey: boolean, currentRoi: Roi): CameraFeedBuildInfoDecision {
    if (pointerType !== "touch") {
      if (!ctrlKey) return { suppress: false, reveal: false, restoreRoi: null };
      this.suppressedPointers.add(pointerId);
      return { suppress: true, reveal: true, restoreRoi: { ...currentRoi } };
    }

    if (this.activeTouchPointers.size === 0) this.initialRoi = { ...currentRoi };
    this.activeTouchPointers.add(pointerId);
    if (this.revealed) {
      this.suppressedPointers.add(pointerId);
      return { suppress: true, reveal: false, restoreRoi: null };
    }
    if (this.activeTouchPointers.size < 4) return { suppress: false, reveal: false, restoreRoi: null };

    this.revealed = true;
    for (const id of this.activeTouchPointers) this.suppressedPointers.add(id);
    return { suppress: true, reveal: true, restoreRoi: this.initialRoi ? { ...this.initialRoi } : { ...currentRoi } };
  }

  end(pointerId: number): boolean {
    const suppress = this.suppressedPointers.delete(pointerId);
    this.activeTouchPointers.delete(pointerId);
    if (this.activeTouchPointers.size === 0) {
      this.initialRoi = null;
      this.revealed = false;
    }
    return suppress;
  }
}
