export interface RadialControlGeometry {
  dialSize: number;
  actionSize: number;
  neutralSize: number;
  dialInlineInset: number;
  dialBlockInset: number;
  confirmInlineEnd: number;
  confirmBottom: number;
  neutralInlineEnd: number;
  neutralBottom: number;
}

export interface RadialControlSafeAreaInsets {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

const RADIAL_CONTROL_GEOMETRY_PROPERTIES = [
  ["dialSize", "--qr-dial-size"],
  ["actionSize", "--qr-action-size"],
  ["neutralSize", "--qr-cancel-size"],
  ["dialInlineInset", "--qr-dial-inline-inset"],
  ["dialBlockInset", "--qr-dial-block-inset"],
  ["confirmInlineEnd", "--qr-confirm-inline-end"],
  ["confirmBottom", "--qr-confirm-bottom"],
  ["neutralInlineEnd", "--qr-neutral-inline-end"],
  ["neutralBottom", "--qr-neutral-bottom"],
] as const satisfies ReadonlyArray<readonly [keyof RadialControlGeometry, `--${string}`]>;

const MINIMUM_ACTION_GAP = 4;
const MINIMUM_INTERACTIVE_SIZE = 44;
const ROUNDING_GAP_ALLOWANCE = 0.02;
const clamp = (minimum: number, value: number, maximum: number) => Math.min(maximum, Math.max(minimum, value));
const round = (value: number) => Math.round(value * 100) / 100;
const finiteNonnegative = (value: number) => Number.isFinite(value) ? Math.max(0, value) : 0;

const normalizeSafeArea = (
  width: number,
  height: number,
  safeArea: Partial<RadialControlSafeAreaInsets>,
): RadialControlSafeAreaInsets => {
  const left = Math.min(finiteNonnegative(safeArea.left ?? 0), width);
  const right = Math.min(finiteNonnegative(safeArea.right ?? 0), width - left);
  const top = Math.min(finiteNonnegative(safeArea.top ?? 0), height);
  const bottom = Math.min(finiteNonnegative(safeArea.bottom ?? 0), height - top);
  return { top, right, bottom, left };
};

const containPair = (
  firstOffset: number,
  firstSize: number,
  secondOffset: number,
  secondSize: number,
  extent: number,
): readonly [number, number] => {
  let shift = Math.max(0, -Math.min(firstOffset, secondOffset));
  const shiftedMaximum = Math.max(firstOffset + firstSize, secondOffset + secondSize) + shift;
  if (shiftedMaximum > extent) shift -= shiftedMaximum - extent;
  return [firstOffset + shift, secondOffset + shift];
};

export function resolveRadialControlGeometry(
  width: number,
  height: number,
  safeArea: Partial<RadialControlSafeAreaInsets> = {},
): RadialControlGeometry {
  const stageWidth = finiteNonnegative(width);
  const stageHeight = finiteNonnegative(height);
  const insets = normalizeSafeArea(stageWidth, stageHeight, safeArea);
  const contentWidth = stageWidth - insets.left - insets.right;
  const contentHeight = stageHeight - insets.top - insets.bottom;
  const shortSide = Math.min(contentWidth, contentHeight);
  const responsiveDial = clamp(180, shortSide * 0.62, 260);
  const dialSize = Math.min(responsiveDial, Math.max(0, shortSide - 48));
  const nominalActionSize = clamp(56, dialSize * 0.26, 72);
  const nominalNeutralSize = clamp(48, dialSize * 0.22, 60);
  const actionGap = Math.min(MINIMUM_ACTION_GAP, shortSide / 10);
  const roundingGap = Math.min(ROUNDING_GAP_ALLOWANCE, actionGap);
  const nominalSizeSum = nominalActionSize + nominalNeutralSize;
  const pairSpanPerSizeSum = (1 + 1 / Math.SQRT2) / 2;
  const availablePairSizeSpan = Math.max(0, shortSide - (actionGap + roundingGap) / Math.SQRT2);
  const sizeSumBudget = Math.min(nominalSizeSum, availablePairSizeSpan / pairSpanPerSizeSum);
  const accessibleSizeSum = MINIMUM_INTERACTIVE_SIZE * 2;
  let actionSize: number;
  let neutralSize: number;
  if (sizeSumBudget >= accessibleSizeSum) {
    const nominalDifference = nominalActionSize - nominalNeutralSize;
    const sizeDifference = Math.min(nominalDifference, sizeSumBudget - accessibleSizeSum);
    actionSize = (sizeSumBudget + sizeDifference) / 2;
    neutralSize = (sizeSumBudget - sizeDifference) / 2;
  } else {
    const fallbackScale = nominalSizeSum > 0 ? sizeSumBudget / nominalSizeSum : 0;
    actionSize = nominalActionSize * fallbackScale;
    neutralSize = nominalNeutralSize * fallbackScale;
  }
  const dialInlineInset = Math.min(Math.max(36, actionSize * 0.65), Math.max(0, contentWidth - dialSize));
  const dialBlockInset = Math.min(36, Math.max(0, contentHeight - dialSize));
  const confirmCenterInline = dialInlineInset + dialSize * 0.1 - actionSize / 2;
  const confirmCenterBottom = dialBlockInset + dialSize * 0.857;
  const diagonal = (
    actionSize / 2
    + neutralSize / 2
    + actionGap
    + roundingGap
  ) / Math.SQRT2;
  const [confirmInlineEnd, neutralInlineEnd] = containPair(
    confirmCenterInline - actionSize / 2,
    actionSize,
    confirmCenterInline + diagonal - neutralSize / 2,
    neutralSize,
    contentWidth,
  );
  const [confirmBottom, neutralBottom] = containPair(
    confirmCenterBottom - actionSize / 2,
    actionSize,
    confirmCenterBottom - diagonal - neutralSize / 2,
    neutralSize,
    contentHeight,
  );

  return {
    dialSize: round(dialSize),
    actionSize: round(actionSize),
    neutralSize: round(neutralSize),
    dialInlineInset: round(dialInlineInset),
    dialBlockInset: round(dialBlockInset),
    confirmInlineEnd: round(confirmInlineEnd),
    confirmBottom: round(confirmBottom),
    neutralInlineEnd: round(neutralInlineEnd),
    neutralBottom: round(neutralBottom),
  };
}

export function readRadialControlSafeAreaInsets(element: HTMLElement): RadialControlSafeAreaInsets {
  const style = getComputedStyle(element);
  const value = (property: string) => finiteNonnegative(Number.parseFloat(style.getPropertyValue(property)));
  return {
    top: value("--qr-safe-area-top"),
    right: value("--qr-safe-area-right"),
    bottom: value("--qr-safe-area-bottom"),
    left: value("--qr-safe-area-left"),
  };
}

export function applyRadialControlGeometry(element: HTMLElement, geometry: RadialControlGeometry): void {
  for (const [key, property] of RADIAL_CONTROL_GEOMETRY_PROPERTIES) {
    element.style.setProperty(property, `${geometry[key]}px`);
  }
}

export function radialControlGeometryCssText(geometry: RadialControlGeometry): string {
  return RADIAL_CONTROL_GEOMETRY_PROPERTIES
    .map(([key, property]) => `${property}:${geometry[key]}px`)
    .join(";");
}
